(function(root){const reasons=['涉嫌禁售商品','经营资质问题','商品信息虚假或误导','店铺违规经营','其他问题'];const api={reasons,validate(reason,text,files){if(!reasons.includes(reason))throw Error('请选择举报原因');if(!text.trim())throw Error('请填写举报说明');if(files.length>3)throw Error('最多上传 3 张图片');for(const f of files){if(!['image/jpeg','image/png'].includes(f.type))throw Error('仅支持 JPG、PNG 图片');if(f.size>5*1024*1024)throw Error('每张图片不能超过 5 MB');}},resolve(r,result){if(r.status!=='待处理')throw Error('该举报已经处理');if(!result.trim())throw Error('请填写处理结果说明');return {...r,status:'已处理',result:result.trim(),resolvedAt:new Date().toLocaleString('zh-CN')};}};if(typeof module!=='undefined')module.exports=api;else root.ReportModel=api;})(globalThis);
